import type { JSX } from "@solidjs/web";
import { createMemo, Errored, For, isPending, latest, Loading, Show } from "solid-js";
import { registerFilePreviewEnglish } from "../i18n/locales/en-file-preview.ts";
import { formatUiError } from "../lib/format-error.ts";
import { elementRef } from "../lib/reactive/element-ref.ts";
import { registerEnglishCatalog, t } from "../lib/reactive/i18n.ts";
import { keyboardHintsVisible } from "../lib/reactive/keyboard-hints.ts";
import { createPendingFocus } from "../lib/reactive/pending-focus.ts";
import { createScrollPosition } from "../lib/reactive/scroll-state.ts";
import { defineSolidBridge, type SolidBridgeElement } from "../lib/solid-bridge.ts";
import { type FileKind, fileKindForPath } from "./file-kind.ts";
import { FilePreviewDocument, filePreviewDocumentLink } from "./file-preview-document.tsx";
import { CopyButton } from "./solid/copy-button.tsx";
import { Icon, type IconName } from "./solid/icon.tsx";
import { Kbd } from "./solid/kbd.tsx";
import { PanelLoadingSkeleton } from "./solid/panel-loading-skeleton.tsx";
import styles from "./file-preview-modal.styles.css?inline";
import "./modal-dialog.tsx";
import kbdStyles from "./kbd.css?inline";

registerEnglishCatalog(registerFilePreviewEnglish);

type FilePreviewModalFile = {
  path: string;
  size: string;
  contents: string;
  message?: string;
};
type FilePreviewModalProps = {
  files: FilePreviewModalFile[];
  activePath: string;
  query: string;
  label: string;
  listLabel: string;
  searchPlaceholder: string;
  contextLabel: string;
  emptyTitle: string;
  emptySubtitle: string;
  copyLabel: string;
  layout: "files" | "document";
  directories: string[];
  readInventory: () => void;
  inventoryRequest: () => Promise<void> | undefined;
  readFile: () => void;
  fileRequest: () => Promise<void> | undefined;
  notice: string;
};
type OpenClawFilePreviewModal = SolidBridgeElement<FilePreviewModalProps>;

function FilePreviewContent(props: FilePreviewModalProps, host: OpenClawFilePreviewModal) {
  let modal: HTMLElement | undefined;
  let modalOpen = false;
  type Target = "search" | "item" | "button" | "close" | "body";
  const targets = new Map<HTMLElement, Target>();
  const capture = (target: Target) =>
    elementRef((element: HTMLElement) => {
      targets.set(element, target);
      return () => targets.delete(element);
    });
  // Keyed rows can move without remounting; navigation follows their committed DOM order.
  const ordered = (target: Target) =>
    [...targets]
      .filter(([, kind]) => kind === target)
      .map(([node]) => node)
      .toSorted((left, right) =>
        left.compareDocumentPosition(right) & Node.DOCUMENT_POSITION_FOLLOWING ? -1 : 1,
      );
  const activeItem = () => ordered("item").find((node) => node.classList.contains("is-active"));
  const filteredFiles = createMemo(() => {
    const query = props.layout === "files" ? props.query.trim().toLowerCase() : "";
    return query
      ? props.files.filter((file) => `${file.path}\n${file.contents}`.toLowerCase().includes(query))
      : props.files;
  });
  const activeFile = createMemo(
    () => filteredFiles().find((file) => file.path === props.activePath) ?? filteredFiles()[0],
  );
  // Sibling responses must not replace the settled leaf for the same request.
  const inventoryRequest = createMemo(() => ({ request: props.inventoryRequest() }), {
    equals: (previous, next) => previous.request === next.request,
  });
  const fileRequest = createMemo(() => ({ request: props.fileRequest() }), {
    equals: (previous, next) => previous.request === next.request,
  });
  const label = () => props.label || t("filePreview.label");
  const fileCount = () =>
    filteredFiles().length === props.files.length
      ? t("filePreview.fileCount", { count: String(props.files.length) })
      : t("filePreview.filteredFileCount", {
          count: String(filteredFiles().length),
          total: String(props.files.length),
        });
  const emit = (name: string, detail?: string) =>
    host.dispatchEvent(new CustomEvent(name, { bubbles: true, composed: true, detail }));
  const close = () => emit("file-preview-close");
  const focusModal = () => {
    if (!host.isConnected || !modal?.isConnected || !modalOpen) {
      return;
    }
    const target =
      ordered("search")[0] ?? activeItem() ?? ordered("button")[0] ?? ordered("close")[0];
    target?.focus({ preventScroll: true });
  };
  const select = (path: string) => {
    emit("file-preview-select", path);
    if (props.layout === "files") {
      focusModal();
    }
  };
  const preventItemPointerFocus = (event: Event) => {
    if (props.layout === "files") {
      event.preventDefault();
    }
  };
  const handleKeydown = (event: KeyboardEvent) => {
    if (event.key === "Escape") {
      event.preventDefault();
      event.stopPropagation();
      close();
      return;
    }
    if (event.key !== "ArrowDown" && event.key !== "ArrowUp") {
      return;
    }
    event.preventDefault();
    event.stopPropagation();
    const files =
      props.layout === "document"
        ? ordered("item")
            .filter((button) => !button.closest("details:not([open])"))
            .flatMap((button) =>
              filteredFiles().filter((file) => file.path === button.dataset.path),
            )
        : filteredFiles();
    const current = files.findIndex((file) => file.path === props.activePath);
    const next =
      files[
        Math.max(
          0,
          Math.min(files.length - 1, Math.max(0, current) + (event.key === "ArrowDown" ? 1 : -1)),
        )
      ];
    if (next && next.path !== (files[current] ?? files[0])?.path) {
      select(next.path);
    }
  };
  const handleDocumentLink = (event: MouseEvent) => {
    const filePath = filePreviewDocumentLink(event, activeFile()?.path ?? "SKILL.md");
    const file = props.files.find((candidate) => candidate.path === filePath);
    if (file) {
      select(file.path);
    }
  };
  createScrollPosition(() => ({
    // A sibling inventory read must not move the document being read.
    reset: {
      identity: [
        props.layout,
        props.query,
        activeFile()?.path,
        activeFile()?.contents,
        activeFile()?.message,
      ],
      target: () => ordered("body")[0],
    },
    reveal: {
      identity: [props.activePath, props.query, props.files, props.layout],
      target: activeItem,
    },
  }));
  createPendingFocus(() => ({ path: props.activePath, layout: props.layout }), {
    requested: (next, previous) =>
      !previous || (next.layout === "document" && next.path !== previous.path),
    focus: focusModal,
  });
  const item = (file: FilePreviewModalFile) => (
    <button
      ref={capture("item")}
      class={["item", { "is-active": file.path === activeFile()?.path }]}
      data-path={file.path}
      aria-current={file.path === activeFile()?.path ? "true" : "false"}
      autofocus={props.layout === "document" && file.path === activeFile()?.path}
      onPointerDown={preventItemPointerFocus}
      onMouseDown={preventItemPointerFocus}
      onClick={() => select(file.path)}
    >
      <span class="item-icon">
        <Icon name={FILE_KIND_ICONS[fileKindForPath(file.path)]} />
      </span>
      <span class="item-name" title={file.path}>
        {props.layout === "document" ? file.path.split("/").pop() : file.path}
      </span>
      <Show when={props.layout === "files"}>
        <span class="item-meta">{file.size}</span>
      </Show>
    </button>
  );
  const folder = (prefix: string): JSX.Element => {
    const files = () => filteredFiles().filter((file) => file.path.startsWith(prefix));
    const direct = () => files().filter((file) => !file.path.slice(prefix.length).includes("/"));
    const folders = () =>
      [
        ...new Set(
          [
            ...files().map((file) => file.path),
            ...props.directories.map((directory) => `${directory}/`),
          ]
            .filter((path) => path.startsWith(prefix) && path.slice(prefix.length).includes("/"))
            .map((path) => path.slice(prefix.length).split("/")[0]!),
        ),
      ].toSorted();
    return (
      <>
        <For each={direct()}>{item}</For>
        <For each={folders()}>
          {(name) => (
            <details class="folder" open>
              <summary>
                <Icon name="folder" />
                <span>{name}</span>
              </summary>
              <div>{folder(`${prefix}${name}/`)}</div>
            </details>
          )}
        </For>
      </>
    );
  };
  return (
    <>
      <style>{`${styles}\nopenclaw-file-preview-modal { ${kbdStyles} }`}</style>
      <openclaw-modal-dialog
        prop:initialFocus={() =>
          [...targets.keys()]
            .filter((element) => element.isConnected && element.autofocus)
            .toSorted((left, right) =>
              left.compareDocumentPosition(right) & Node.DOCUMENT_POSITION_FOLLOWING ? -1 : 1,
            )[0] ?? null
        }
        ref={(element) => (modal = element)}
        prop:onOpenChange={(open: boolean) => (modalOpen = open)}
        label={label()}
        style={{
          "--openclaw-modal-width": "min(1100px, 92vw)",
          "--openclaw-modal-max-height": "86vh",
        }}
        onModal-cancel={close}
        onKeyDown={handleKeydown}
      >
        <div class="modal">
          <header class="head">
            <Show
              when={props.layout === "document"}
              fallback={
                <>
                  <span class="search-icon">⌕</span>
                  <input
                    ref={capture("search")}
                    class="search"
                    autofocus
                    placeholder={props.searchPlaceholder || t("filePreview.searchPlaceholder")}
                    value={props.query}
                    onInput={(event) =>
                      emit("file-preview-query-change", event.currentTarget.value)
                    }
                  />
                  <span class="state">{fileCount()}</span>
                </>
              }
            >
              <h1 class="heading">{label()}</h1>
              <button
                ref={capture("close")}
                class="close-button"
                type="button"
                aria-label={t("common.close")}
                autofocus={!activeFile()}
                onClick={close}
              >
                <Icon name="x" />
              </button>
            </Show>
          </header>
          <Show when={props.notice}>
            <p class="notice" role="status">
              {props.notice}
            </p>
          </Show>
          {/* Owners initialize reads to null before opening; these probes keep the shell mounted. */}
          <div
            class={["body", { tree: props.layout === "document" }]}
            aria-busy={
              isPending(() => props.readInventory()) || isPending(() => props.readFile())
                ? "true"
                : "false"
            }
          >
            <aside class="list">
              <Show when={props.layout === "files"}>
                <div class="list-section">
                  {props.listLabel || t("filePreview.listLabel")} · {filteredFiles().length}
                </div>
              </Show>
              {/* Request accessors bypass held bridge props; keyed Show requires a callback argument. */}
              <Show when={latest(inventoryRequest)} keyed>
                {(_request) => (
                  <Errored fallback={() => null}>
                    <Loading
                      fallback={
                        <PanelLoadingSkeleton
                          variant="file-list"
                          label={t("common.loading")}
                          compact
                        />
                      }
                    >
                      {
                        (props.readInventory(),
                        filteredFiles().length === 0 ? (
                          <div class="empty-list">{t("filePreview.noMatches")}</div>
                        ) : props.layout === "document" ? (
                          folder("")
                        ) : (
                          <For each={filteredFiles()}>{item}</For>
                        ))
                      }
                    </Loading>
                  </Errored>
                )}
              </Show>
            </aside>
            <Show when={latest(fileRequest)} keyed>
              {(_request) => (
                <Errored
                  fallback={(error) => (
                    <section class="detail empty">
                      <p role="alert">{formatUiError(error())}</p>
                      <button
                        ref={capture("button")}
                        class="button"
                        onClick={() => emit("file-preview-retry")}
                      >
                        {t("common.retry")}
                      </button>
                    </section>
                  )}
                >
                  <Loading
                    fallback={
                      <section class="detail">
                        <div ref={capture("body")} class="detail-body">
                          <PanelLoadingSkeleton
                            variant="document"
                            label={t("common.loading")}
                            compact
                          />
                        </div>
                      </section>
                    }
                  >
                    {
                      (props.readFile(),
                      (
                        <Show
                          when={activeFile()}
                          fallback={
                            <section class="detail empty">
                              <p class="empty-title">
                                {props.emptyTitle || t("filePreview.emptyTitle")}
                              </p>
                              <p class="empty-subtitle">
                                {props.emptySubtitle || t("filePreview.emptySubtitle")}
                              </p>
                            </section>
                          }
                        >
                          {(file) => (
                            <section class="detail">
                              <Show when={props.layout === "files"}>
                                <div class="detail-head">
                                  <div class="detail-title-row">
                                    <h2 class="title">{file().path}</h2>
                                    <Show when={file().contents}>
                                      <CopyButton
                                        text={file().contents}
                                        idleLabel={props.copyLabel || t("filePreview.copyFile")}
                                        bare
                                      />
                                    </Show>
                                  </div>
                                  <div class="chips">
                                    <span class="chip accent">{fileKind(file().path)}</span>
                                    <span class="chip">{file().size}</span>
                                    <span class="chip">{t("filePreview.readOnly")}</span>
                                    <Show when={props.contextLabel}>
                                      <span class="chip ok">{props.contextLabel}</span>
                                    </Show>
                                  </div>
                                </div>
                              </Show>
                              <div ref={capture("body")} class="detail-body">
                                <FilePreviewDocument
                                  path={file().path}
                                  content={file().contents}
                                  message={file().message}
                                  markdown={props.layout === "document"}
                                  onClick={handleDocumentLink}
                                />
                              </div>
                            </section>
                          )}
                        </Show>
                      ))
                    }
                  </Loading>
                </Errored>
              )}
            </Show>
          </div>
          <Show when={props.layout === "files"}>
            <footer class="foot">
              <Show when={keyboardHintsVisible()}>
                <span class="foot-group">
                  <Kbd keys={["↑", "↓"]} class="kbd" /> {t("filePreview.navigate")}
                </span>
              </Show>
              <openclaw-modal-actions>
                <button ref={capture("button")} class="button" onClick={close}>
                  {t("common.close")} <Kbd keys="esc" class="kbd" />
                </button>
              </openclaw-modal-actions>
            </footer>
          </Show>
        </div>
      </openclaw-modal-dialog>
    </>
  );
}

export const FilePreviewModal = defineSolidBridge<FilePreviewModalProps>(
  "openclaw-file-preview-modal",
  FilePreviewContent,
  {
    properties: {
      files: { default: [], attribute: false },
      activePath: { default: "" },
      query: { default: "" },
      label: { default: "" },
      listLabel: { default: "" },
      searchPlaceholder: { default: "" },
      contextLabel: { default: "" },
      emptyTitle: { default: "" },
      emptySubtitle: { default: "" },
      copyLabel: { default: "" },
      layout: { default: "files" },
      directories: { default: [], attribute: false },
      readInventory: { default: () => {}, attribute: false },
      inventoryRequest: { default: () => undefined, attribute: false },
      readFile: { default: () => {}, attribute: false },
      fileRequest: { default: () => undefined, attribute: false },
      notice: { default: "" },
    },
  },
);

function fileKind(path: string): string {
  const ext = path.split(".").pop()?.toLowerCase() ?? "";
  const map: Record<string, string> = {
    md: "Markdown",
    txt: t("filePreview.kind.text"),
    json: "JSON",
    yaml: "YAML",
    yml: "YAML",
    ts: "TypeScript",
    js: "JavaScript",
    py: "Python",
    sh: t("filePreview.kind.shell"),
  };
  return Object.hasOwn(map, ext) ? map[ext]! : ext ? ext.toUpperCase() : t("filePreview.kind.file");
}
const FILE_KIND_ICONS: Record<FileKind, IconName> = {
  code: "fileCode",
  component: "layoutGrid",
  data: "braces",
  file: "fileText",
  image: "image",
  markdown: "book",
  package: "box",
  shell: "terminal",
  skill: "pencilSparkles",
};
declare global {
  interface HTMLElementTagNameMap {
    "openclaw-file-preview-modal": OpenClawFilePreviewModal;
  }
}
